fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    // If maxsplit is zero, no splitting takes place.
    if maxsplit == 0 {
        // Each element wrapped in a vec with just itself.
        return a.into_iter().map(|s| vec![s]).collect();
    }

    let sep = sep.as_str();
    a.into_iter()
        .map(|s| {
            // If input string is empty, return vec with one empty string
            if s.is_empty() {
                return vec![String::new()];
            }

            // Use rsplitn: number of parts is maxsplit + 1,
            // so number of splits = maxsplit.
            s.rsplitn((maxsplit as usize) + 1, sep)
                .map(|part| part.to_string())
                .collect::<Vec<_>>()
                // rsplitn returns parts starting from right (last split to left),
                // but we want left to right, so reverse to get original order of parts.
                .into_iter()
                .rev()
                .collect()
        })
        .collect()
}